namespace ghidra.features.bsim.query.elastic;

using ghidra.features.bsim.query.description;

public abstract class IDElasticResolution {
	public string idString;

	public abstract void resolve(ElasticDatabase database,ExecutableRecord exe);

	public static class ExternalFunction : IDElasticResolution {
		private string exeName;			// Name of executable containing external function
		private string funcName;		// Name of external function

		public ExternalFunction(string exe,string func) {
			exeName = exe;
			funcName = func;
			idString = null;
		}

		/* @Override */
		public void resolve(ElasticDatabase database,ExecutableRecord exe)
    {
			if (idString == null)
				idString = database.recoverExternalFunctionId(exeName, funcName, exe.getArchitecture());
		}
	}
}
